import {escapeHTML as e,bytes,move,uniqueSlug,validate,cover,mediaURL} from './shared.js';
import * as store from './storage.js';import {optimize} from './compress.js';import {GitHub} from './github.js';
const $=s=>document.querySelector(s),base='/portfolio/';
let revision=0;
let state,github=null,view='projects',selected=null,search='',filter='',page=1,mediaPage=1,busy=false,dirty=false,saving=Promise.resolve(),timer,dragIndex,objectURLs=new Map(),mediaFailures=[];
const notice=(message,error=false)=>{const n=$('#notice');n.hidden=false;n.className=error?'error':'';n.textContent=message;};
const fail=error=>{notice(error.message||String(error),true);console.error(error.message||error);};
const p=()=>state.content.projects.find(p=>p.id===selected);
const field=(label,key,value,type='text',wide=false)=>`<label class="field ${wide?'wide':''}">${label}${type==='textarea'?`<textarea data-field="${key}" rows="5">${e(value)}</textarea>`:`<input data-field="${key}" type="${type}" value="${e(value)}">`}</label>`;
const btn=(action,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function save(){clearTimeout(timer);dirty=true;const savingRevision=++revision;$('#save-status').textContent='Saving on device…';const snapshot=structuredClone(state);saving=saving.catch(()=>{}).then(()=>store.write('state','draft',snapshot)).then(()=>{if(savingRevision!==revision)return;dirty=false;$('#save-status').className='save-dot';$('#save-status').textContent='Saved on this device';}).catch(err=>{$('#save-status').className='save-dot error';$('#save-status').textContent='Not saved';dirty=true;throw Error('Draft could not be saved. Device storage may be full. Download a backup before closing. '+err.message);});return saving;}
function changed(){revision++;state.modified=true;dirty=true;$('#save-status').textContent='Unsaved changes';clearTimeout(timer);timer=setTimeout(()=>save().catch(fail),450);}
async function ask(title,text,ok='Continue'){const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-ok').textContent=ok;d.returnValue='';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
function totalMedia(){const map=new Map();state.content.projects.forEach(p=>p.gallery.forEach(m=>map.set(m.id,{...m,project:p.title})));return [...map.values()];}
function storageSummary(){const list=totalMedia(),total=list.reduce((n,m)=>n+(m.bytes||0)+(m.thumbBytes||0),0);return {list,total};}
async function hydrateImages(){for(const img of document.querySelectorAll('img[data-media]')){const path=img.dataset.media;try{let url=objectURLs.get(path);if(!url){const blob=await store.read('media',path);if(blob){url=URL.createObjectURL(blob);objectURLs.set(path,url);}}if(url&&img.isConnected)img.src=url;}catch{}}}
function image(m,cls=''){return m?`<img class="${cls}" src="${e(mediaURL(m.thumb,base))}" data-media="${e(m.thumb)}" alt="${e(m.alt)}" loading="lazy">`:'<div class="empty-art">✳</div>';}
function heading(title,subtitle,actions=''){return `<div class="editor-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions}</div>`;}
function projectList(){const all=state.content.projects,found=all.filter(x=>(!search||(x.title+' '+x.category).toLowerCase().includes(search.toLowerCase()))&&(!filter||x.status===filter)),pages=Math.max(1,Math.ceil(found.length/12));page=Math.min(page,pages);return heading('Your projects','A place for every idea. Make your next one visible.',btn('add','+ New project',''))+`<div class="stats"><div class="stat"><small>Total projects</small><strong>${all.length}</strong></div><div class="stat"><small>Published</small><strong>${all.filter(p=>p.status==='published').length}</strong></div><div class="stat"><small>Drafts</small><strong>${all.filter(p=>p.status==='draft').length}</strong></div></div><div class="editor-toolbar"><input id="search" aria-label="Search projects" placeholder="Search your projects…" value="${e(search)}"><select id="filter" aria-label="Project status"><option value="">All projects</option><option value="published" ${filter==='published'?'selected':''}>Published</option><option value="draft" ${filter==='draft'?'selected':''}>Drafts</option></select></div><div class="editor-cards">${found.slice((page-1)*12,page*12).map(x=>{const i=all.indexOf(x);return `<article class="editor-card"><div class="editor-cover">${image(cover(x))}<span class="badge ${x.status}">${x.status==='published'?'Published':'Draft'}${x.featured?' · Featured':''}</span></div><div class="editor-card-info"><small>${e(x.category||'UNCATEGORIZED')}</small><h2>${e(x.title)}</h2><p>${x.gallery.length} images · ${e(x.date?.slice(0,4)||'No date')}</p></div><div class="card-actions">${btn('edit','Edit project','secondary edit-project',`data-id="${e(x.id)}"`)}${btn('project-up','↑','secondary',`data-id="${e(x.id)}" aria-label="Move ${e(x.title)} up" ${i===0?'disabled':''}`)}${btn('project-down','↓','secondary',`data-id="${e(x.id)}" aria-label="Move ${e(x.title)} down" ${i===all.length-1?'disabled':''}`)}</div></article>`;}).join('')}</div>${!found.length?'<div class="empty"><h2>A new chapter.</h2><p>Add a project to start shaping your portfolio.</p></div>':''}<div class="pagination">${btn('previous','← Previous','secondary',page===1?'disabled':'')}<span>${page} / ${pages}</span>${btn('next','Next →','secondary',page===pages?'disabled':'')}</div>`;}
function editProject(){const x=p();if(!x){view='projects';return projectList();}return heading(e(x.title),'Shape the story. Everything saves on this device.',btn('back','← All projects'))+`<div class="project-edit-layout"><div><section class="panel"><h2>Project details</h2><div class="form-grid">${field('Project title','title',x.title)}${field('Category','category',x.category)}${field('Subtitle','subtitle',x.subtitle,'text',true)}${field('Description / project story','description',x.description,'textarea',true)}${field('Project date','date',x.date,'date')}${field('Your role','role',x.role)}${field('Project URL slug','slug',x.slug,'text',true)}<label class="check-field"><input type="checkbox" data-field="featured" ${x.featured?'checked':''}> Feature on homepage</label><label class="check-field"><input type="checkbox" data-field="demo" ${x.demo?'checked':''}> Label as concept study</label></div></section><section class="panel"><h2>Gallery <small>${x.gallery.length} images</small></h2><label class="upload-zone"><strong>Bring your project to life</strong><small>Select multiple JPEG, PNG, WebP or AVIF images.<br>Images are resized and compressed here before upload.</small><input id="upload" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple></label><div class="compression-options"><label>Quality <input id="quality" type="range" min="60" max="92" value="${state.quality||82}"><output id="quality-value">${state.quality||82}%</output></label><label>Maximum edge <select id="max-edge"><option value="1920">1920 px</option><option value="1600" ${state.maxEdge===1600?'selected':''}>1600 px</option></select></label></div><progress id="upload-progress" max="100" value="0" hidden></progress><p id="gallery-progress" role="status"></p><p class="field-help">Drag images to reorder, or use the arrow buttons. Set any image as the project cover. Originals stay on your device.</p><div class="gallery-edit">${x.gallery.map((m,i)=>`<article class="media-tile" draggable="true" data-index="${i}">${image(m)}<div><input data-alt="${e(m.id)}" aria-label="Image description ${i+1}" value="${e(m.alt)}" placeholder="Describe this image"><p>${bytes(m.bytes||0)} + ${bytes(m.thumbBytes||0)} thumbnail</p><div class="actions">${btn('cover',x.cover===m.id?'✓ Cover':'Set cover',x.cover===m.id?'':'secondary',`data-id="${m.id}"`)}${btn('image-up','←','secondary',`data-id="${m.id}" aria-label="Move image ${i+1} earlier" ${i===0?'disabled':''}`)}${btn('image-down','→','secondary',`data-id="${m.id}" aria-label="Move image ${i+1} later" ${i===x.gallery.length-1?'disabled':''}`)}${btn('remove-image','Remove','secondary',`data-id="${m.id}"`)}</div></div></article>`).join('')}</div></section></div><aside class="project-edit-side"><section class="panel"><h2>Publishing</h2><p class="publish-summary"><strong>${x.status==='published'?'Included in the public site':'Draft · hidden from the site'}</strong>Local edits appear online only after a successful GitHub deployment.</p><div class="actions">${btn('preview','Preview project ↗')}${btn('publish-project','Publish this project','')}${btn('draft',x.status==='draft'?'Save draft':'Move to draft')}${btn('duplicate','Duplicate project')}</div></section><section class="panel"><h2>A little care.</h2><p>Use useful image descriptions for accessibility. Choose a strong cover; it sets the tone for your project.</p>${btn('delete','Delete project','danger')}</section></aside></div>`;}
function siteForm(){const s=state.content.site;return heading('Your website','Your voice, from the first impression to the last detail.')+`<section class="panel"><h2>Homepage & identity</h2><div class="form-grid">${field('Your name','name',s.name)}${field('Professional title','role',s.role)}${field('Homepage headline','headline',s.headline,'textarea',true)}${field('Introduction','intro',s.intro,'textarea',true)}${field('Search engine description','description',s.description,'textarea',true)}</div></section><section class="panel"><h2>About</h2><div class="form-grid">${field('Your story','about',s.about,'textarea',true)}</div></section><section class="panel"><h2>Contact</h2><div class="form-grid">${field('Email address','email',s.email,'email')}${field('Phone number','phone',s.phone||'','tel')}${field('Contact link (optional)','contactUrl',s.contactUrl,'url',true)}${field('Contact headline','contactTitle',s.contactTitle,'textarea',true)}${field('Contact introduction','contactText',s.contactText,'textarea',true)}</div></section><section class="panel"><h2>Social links</h2><p>These appear in your footer and on your Contact page. Use complete https:// links.</p><div class="form-grid">${(s.socials||[]).map((l,i)=>`<label class="field">Platform name<input data-social="${i}" data-key="label" value="${e(l.label)}" placeholder="Instagram"></label><label class="field">Profile URL<div class="actions"><input data-social="${i}" data-key="url" value="${e(l.url)}" type="url" placeholder="https://…">${btn('remove-social','Remove','secondary',`data-index="${i}"`)}</div></label>`).join('')}</div><div class="actions">${btn('add-social','+ Add social link')}</div></section>`;}
function mediaLibrary(){const {list,total}=storageSummary(),repoBytes=(state.repoSize||0)*1024;const max=48,pages=Math.max(1,Math.ceil(list.length/max));mediaPage=Math.min(mediaPage,pages);return heading('Media library','Optimized images, ready for a growing body of work.')+`<div class="stats"><div class="stat"><small>Unique images</small><strong>${list.length}</strong></div><div class="stat"><small>Referenced media</small><strong>${bytes(total)}</strong></div><div class="stat"><small>GitHub repository estimate</small><strong>${state.repoSize!=null?bytes(repoBytes):'Connect'}</strong></div></div><section class="panel"><h2>Space to create</h2><div class="storage-meter"><progress max="1073741824" value="${Math.max(repoBytes,total)}"></progress></div><p>${Math.max(repoBytes,total)>750*1024*1024?'Storage warning: repository is approaching 1 GB. Move future media to external storage.':'Storage warning begins at 750 MB. Publishing stops at an estimated 900 MB to leave room below GitHub Pages’ 1 GB size limit.'}</p><p>Git history retains previous files. Deleting an image from a gallery does not erase its history or immediately reclaim repository storage. HTTPS media URLs are supported in the content model for a future external storage provider.</p><p id="device-storage">Checking device storage…</p></section><div class="media-library">${list.slice((mediaPage-1)*max,mediaPage*max).map(m=>`<article class="panel">${image(m)}<h3>${e(m.alt||m.project)}</h3><p>${e(m.project)} · ${bytes((m.bytes||0)+(m.thumbBytes||0))}</p></article>`).join('')}</div><div class="pagination">${btn('media-prev','← Previous','secondary',mediaPage===1?'disabled':'')}<span>${mediaPage} / ${pages}</span>${btn('media-next','Next →','secondary',mediaPage===pages?'disabled':'')}</div>`;}
function settings(){const cfg=state.config;return heading('Publishing','One repository. One deployment. Your portfolio, up to date.')+`<div class="two-panels"><section class="panel"><h2>Connect to GitHub</h2><p>Use a fine-grained personal access token scoped only to your portfolio repository.</p><div class="form-grid">${field('GitHub username','owner',cfg.owner)}${field('Repository','repo',cfg.repo)}${field('Branch','branch',cfg.branch)}<label class="field wide">Access token<input id="token" class="token-input" type="password" autocomplete="off" spellcheck="false" placeholder="Paste token for this session only"></label></div><p class="token-help">Repository permissions: <strong>Contents: read and write</strong>, <strong>Actions: read</strong>, and automatic Metadata: read. No account-wide access is needed. <a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create a fine-grained token ↗</a></p><p class="token-help">Your token is kept only in memory and is cleared when you reload or disconnect. Never share it in chat. On a public repository, committed drafts can be read on GitHub even though they are excluded from the website.</p><div class="actions">${btn('connect',github?'Reconnect':'Connect GitHub','')}${btn('disconnect','Disconnect')}${btn('pull','Load latest from GitHub')}</div></section><section class="panel"><h2>Deployment</h2><p class="status-detail" id="deployment-status">${e(state.deployment?.message||'No deployment started from this device yet.')}</p>${state.deployment?.url?`<p><a class="text-link" href="${e(state.deployment.url)}" target="_blank" rel="noopener">View GitHub build ↗</a></p>`:''}<div class="actions">${btn('check-deploy','Check deployment')}${btn('publish','Publish changes','')}</div><p class="field-help">“Live verified” means the website’s release marker matches the exact commit, after GitHub Actions reports success.</p></section></div><section class="panel"><h2>Keep a copy</h2><p>Download a portable backup of your content and optimized local images. Backups never include your token. Keep the backup before clearing browser data or moving devices.</p><div class="actions">${btn('backup','Download backup')}<label class="button secondary">Restore backup<input id="restore" type="file" accept="application/json" hidden></label></div><p class="field-help">Local drafts belong to this browser and device. GitHub holds the last published content; your backup also includes unpublished edits.</p></section>`;}
function render(){if(busy)return;$('#nav-count').textContent=state.content.projects.length;$('#breadcrumb').textContent='Workspace / '+({projects:'Projects',edit:'Project details',site:'Website content',media:'Media library',settings:'Publishing'}[view]);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(view==='edit'?'projects':view)));$('#content').innerHTML=view==='projects'?projectList():view==='edit'?editProject():view==='site'?siteForm():view==='media'?mediaLibrary():settings();hydrateImages();if(view==='media')navigator.storage?.estimate().then(r=>{const el=$('#device-storage');if(el)el.textContent=`Device storage: ${bytes(r.usage||0)} used of ${bytes(r.quota||0)} available quota. Browser clearing can remove local drafts.`;}).catch(()=>{});}
function setBusy(value){busy=value;document.querySelectorAll('#content button,#content input,#content select,#content textarea,[data-view],#publish-all').forEach(el=>{if(value){el.dataset.wasDisabled=el.disabled?'1':'0';el.disabled=true;}else{el.disabled=el.dataset.wasDisabled==='1';delete el.dataset.wasDisabled;}});}
async function upload(files){if(!files.length)return;const project=p();await save();setBusy(true);const progress=$('#upload-progress'),status=$('#gallery-progress');progress.hidden=false;const errors=[];let added=0,before=0,after=0;try{await store.persist();for(let i=0;i<files.length;i++){status.textContent=`Optimizing ${i+1} of ${files.length}: ${files[i].name}`;try{const result=await optimize(files[i],(state.quality||82)/100,state.maxEdge||1920),id=crypto.randomUUID(),src=`media/${id}.webp`,thumb=`media/${id}-thumb.webp`;await store.write('media',src,result.large);await store.write('media',thumb,result.thumb);project.gallery.push({id,src,thumb,alt:files[i].name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' '),bytes:result.large.size,thumbBytes:result.thumb.size,width:result.width,height:result.height});if(!project.cover)project.cover=id;state.modified=true;await save();added++;before+=result.originalBytes;after+=result.large.size+result.thumb.size;}catch(err){errors.push(err.message);}progress.value=Math.round((i+1)/files.length*100);}}finally{setBusy(false);render();}notice(`${added} image${added===1?'':'s'} optimized and saved on this device. ${bytes(before)} originals → ${bytes(after)} including thumbnails.${errors.length?'\n'+errors.join('\n'):''}`,!!errors.length);}
async function connect(){await save();const token=$('#token')?.value.trim();if(!token)throw Error('Enter a repository-scoped access token to connect. It is not saved.');if(state.config.repo!=='portfolio'||state.config.branch!=='main')throw Error('This installation uses repository portfolio and branch main.');const candidate=new GitHub({...state.config,token});setBusy(true);try{const r=await candidate.connect();validate(r.content);if(state.baseline&&state.baseline!==r.sha&&state.modified){notice('GitHub content has changed. Your local draft is preserved. Download a backup before using “Load latest from GitHub”.',true);}else if(!state.modified){state.content=r.content;state.baseline=r.sha;}else if(!state.baseline){if(JSON.stringify(state.original)!==JSON.stringify(r.content))throw Error('Local starting content differs from GitHub. Download your backup and load the latest GitHub content before publishing.');state.baseline=r.sha;}github=candidate;state.repoSize=r.repo.size;$('#connection-label').textContent=`Connected as ${r.user}`;await save();notice(`Connected to ${state.config.owner}/${state.config.repo}. Token stays in memory for this session.`);}finally{if($('#token'))$('#token').value='';setBusy(false);render();}}
async function pull(){if(!github)throw Error('Connect GitHub first.');if(state.modified&&!await ask('Replace local content?','Download a backup first if you want to retain local edits. This loads GitHub’s latest content onto this device.','Load latest'))return;const remote=await github.content();validate(remote.content);state.content=remote.content;state.original=structuredClone(remote.content);state.baseline=remote.sha;state.modified=false;await save();render();notice('Latest GitHub content loaded and saved on this device.');}
async function publish(projectOnly=false){if(!github){view='settings';render();notice('Connect GitHub to publish. Your draft is saved on this device.');return;}const before=projectOnly?p().status:null;if(projectOnly)p().status='published';try{validate(state.content);}catch(err){if(projectOnly)p().status=before;throw err;}
 const pub=state.content.projects.filter(p=>p.status==='published').length,drafts=state.content.projects.length-pub;
 if(!await ask('Publish website changes?',`This commits all saved content and optimized images to ${state.config.owner}/${state.config.repo}. ${pub} published projects will appear on the site; ${drafts} drafts will remain hidden from the site. Draft text is still readable in a public GitHub repository.`, 'Publish to GitHub')){if(projectOnly)p().status=before;return;}
 state.modified=true;await save();const content=structuredClone(state.content);setBusy(true);try{const paths=[...new Set(content.projects.flatMap(p=>p.gallery.flatMap(m=>[m.src,m.thumb])))];const media=[];for(const path of paths){const blob=await store.read('media',path);if(blob)media.push({path,blob});}
 const repo=await github.api(github.root);state.repoSize=repo.size;const total=(repo.size||0)*1024+media.reduce((n,m)=>n+m.blob.size,0);if(total>900*1024*1024)throw Error('Repository storage would exceed the 900 MB safety threshold. Move media to external storage before publishing.');
 const result=await github.publish({content,baseline:state.baseline,media,onProgress:notice});
 state.baseline=result.baseline;state.modified=false;state.original=structuredClone(content);state.deployment={sha:result.commit,message:'GitHub commit saved. Waiting for deployment…',url:`https://github.com/${state.config.owner}/${state.config.repo}/actions`};await save();
 // Uploaded blobs remain available for preview until deployment; mark them for cleanup after live verification.
 state.deployment.uploaded=media.map(m=>m.path);state.deployment.polls=0;await save();notice('GitHub commit saved. Checking the deployment…');
 }finally{setBusy(false);render();}
 await checkDeployment(true);
}
let pollTimer;
async function checkDeployment(auto=false){if(!state.deployment?.sha)throw Error('No deployment has been started from this device.');if(!github)throw Error('Connect GitHub to check deployment status.');clearTimeout(pollTimer);let message;try{const run=await github.deployment(state.deployment.sha);if(run.url)state.deployment.url=run.url;
 if(run.status==='completed'&&run.conclusion!=='success'){message=`Deployment ${run.conclusion}. Your GitHub commit is saved, but the live site has not been verified. Open the GitHub build for details.`;auto=false;}
 else if(run.conclusion==='success'){const r=await fetch(base+'release.json?v='+Date.now(),{cache:'no-store'});const release=r.ok?await r.json():{};if(release.sha===state.deployment.sha){message='Live verified — your website is serving commit '+release.sha.slice(0,7)+'.';auto=false;for(const path of state.deployment.uploaded||[]){await store.remove('media',path);}state.deployment.uploaded=[];}else message='GitHub deployment succeeded. Waiting for the live website to serve this commit…';}
 else message=run.status==='waiting'?'Commit saved. Waiting for GitHub Actions to start…':`GitHub deployment: ${run.status.replaceAll('_',' ')}…`;
 }catch(err){message='Commit remains saved. Status check failed: '+err.message;auto=false;}
 state.deployment.message=message;await save();notice(message,/failed|cancelled|failure|timed_out/.test(message));if($('#deployment-status'))$('#deployment-status').textContent=message;
 if(auto){state.deployment.polls=(state.deployment.polls||0)+1;if(state.deployment.polls<24)pollTimer=setTimeout(()=>checkDeployment(true).catch(fail),15000);else notice('Commit saved; live deployment is not verified yet. Use Check deployment to retry.');}
}
async function backup(){await save();const media={};const referenced=new Set(state.content.projects.flatMap(p=>p.gallery.flatMap(m=>[m.src,m.thumb])));for(const key of (await store.keys('media')).filter(k=>referenced.has(k))){const blob=await store.read('media',key);media[key]=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});}const blob=new Blob([JSON.stringify({format:'astra-backup-1',state,media})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`astra-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notice('Backup downloaded. It includes your draft and optimized local images, never your token.');}
async function restore(file){if(!file)return;if(file.size>250*1024*1024)throw Error('Backup exceeds 250 MB. Restore large libraries through GitHub.');const b=JSON.parse(await file.text());if(b.format!=='astra-backup-1')throw Error('This is not an ASTRA backup');validate(b.state?.content);for(const [path,data]of Object.entries(b.media||{})){if(!/^media\/[\w-]+(?:-thumb)?\.webp$/.test(path)||typeof data!=='string'||!data.startsWith('data:image/webp;base64,'))throw Error('Backup contains an invalid image');}
 if(!await ask('Restore this backup?','This replaces your current local draft. Download a backup of current edits first if needed.','Restore'))return;
 for(const [path,data]of Object.entries(b.media||{})){const blob=new Blob([Uint8Array.from(atob(data.split(',')[1]),c=>c.charCodeAt(0))],{type:'image/webp'});if(blob.size>3*1024*1024)throw Error('Backup image exceeds 3 MB');await store.write('media',path,blob);}
 const config=state.config;state={...b.state,config,modified:true};github=null;$('#connection-label').textContent='Working on this device';await save();render();notice('Backup restored. Reconnect GitHub before publishing.');}
async function action(name,el){const x=p(),id=el.dataset.id;
 if(name==='add'){const project={id:crypto.randomUUID(),slug:uniqueSlug('Untitled project',state.content.projects),title:'Untitled project',subtitle:'',description:'',category:'',date:new Date().toISOString().slice(0,10),role:'',featured:false,status:'draft',demo:false,cover:'',gallery:[]};state.content.projects.unshift(project);selected=project.id;view='edit';state.modified=true;await save();render();return;}
 if(name==='edit'){selected=id;view='edit';render();return;}
 if(name==='back'){view='projects';render();return;}
 if(name==='previous'||name==='next'){page+=name==='next'?1:-1;render();return;}
 if(name==='media-prev'||name==='media-next'){mediaPage+=name==='media-next'?1:-1;render();return;}
 if(name==='project-up'||name==='project-down'){const i=state.content.projects.findIndex(p=>p.id===id);move(state.content.projects,i,i+(name==='project-up'?-1:1));}
 else if(name==='duplicate'){const clone=structuredClone(x);clone.id=crypto.randomUUID();clone.title+=' — copy';clone.slug=uniqueSlug(clone.title,state.content.projects);clone.status='draft';state.content.projects.splice(state.content.projects.indexOf(x)+1,0,clone);selected=clone.id;}
 else if(name==='delete'){if(!await ask('Delete this project?',`“${x.title}” will be removed from this draft. Publish changes to remove it from the live website. Git history retains prior versions.`,'Delete project'))return;state.content.projects=state.content.projects.filter(p=>p.id!==x.id);view='projects';}
 else if(name==='draft'){x.status='draft';notice('Draft saved locally. Publish changes to remove a previously published project from the live site.');}
 else if(name==='cover'){x.cover=id;}
 else if(name==='remove-image'){if(!await ask('Remove image?','This removes the image from this gallery. Referenced copies in other projects and Git history remain.','Remove image'))return;x.gallery=x.gallery.filter(m=>m.id!==id);if(x.cover===id)x.cover=x.gallery[0]?.id||'';}
 else if(name==='image-up'||name==='image-down'){const i=x.gallery.findIndex(m=>m.id===id);move(x.gallery,i,i+(name==='image-up'?-1:1));}
 else if(name==='preview'){await save();window.open(base+'preview/?project='+encodeURIComponent(x.id),'_blank','noopener');return;}
 else if(name==='publish-project')return publish(true);
 else if(name==='publish')return publish();
 else if(name==='connect')return connect();
 else if(name==='disconnect'){github=null;clearTimeout(pollTimer);$('#connection-label').textContent='Working on this device';render();notice('Disconnected. Token cleared from memory.');return;}
 else if(name==='pull')return pull();
 else if(name==='check-deploy')return checkDeployment();
 else if(name==='backup')return backup();
 else if(name==='add-social'){(state.content.site.socials ||= []).push({label:'',url:''});}
 else if(name==='remove-social'){state.content.site.socials.splice(Number(el.dataset.index),1);}
 else return;
 state.modified=true;await save();render();
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-view]');if(!el||busy)return;if(el.dataset.view){view=el.dataset.view;render();return;}action(el.dataset.action,el).catch(fail);});
$('#publish-all').addEventListener('click',()=>publish().catch(fail));
document.addEventListener('input',event=>{const el=event.target;if(busy)return;
 if(el.id==='search'){search=el.value;page=1;const pos=el.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);return;}
 if(el.id==='quality'){state.quality=Number(el.value);$('#quality-value').textContent=el.value+'%';changed();return;}
 if(el.dataset.field){const obj=view==='site'?state.content.site:view==='settings'?state.config:p();if(view==='settings'){github=null;document.querySelector('#connection-label').textContent='Working on this device';}obj[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;changed();}
 if(el.dataset.alt){const m=p().gallery.find(m=>m.id===el.dataset.alt);m.alt=el.value;changed();}
 if(el.dataset.social!==undefined){state.content.site.socials[Number(el.dataset.social)][el.dataset.key]=el.value;changed();}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='filter'){filter=el.value;page=1;render();}if(el.id==='upload')upload([...el.files]).catch(fail);if(el.id==='restore')restore(el.files[0]).catch(fail);if(el.id==='max-edge'){state.maxEdge=Number(el.value);changed();}});
document.addEventListener('dragstart',event=>{const tile=event.target.closest('.media-tile');if(tile&&!busy){dragIndex=Number(tile.dataset.index);tile.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(dragIndex));}});
document.addEventListener('dragend',()=>{document.querySelectorAll('.dragging').forEach(el=>el.classList.remove('dragging'));dragIndex=undefined;});
document.addEventListener('dragover',event=>{if(event.target.closest('.media-tile'))event.preventDefault();});
document.addEventListener('drop',event=>{const tile=event.target.closest('.media-tile');if(tile&&dragIndex!==undefined&&!busy){event.preventDefault();move(p().gallery,dragIndex,Number(tile.dataset.index));state.modified=true;save().then(render).catch(fail);dragIndex=undefined;}});
window.addEventListener('beforeunload',event=>{if(dirty||busy){event.preventDefault();event.returnValue='';}});
try{state=await store.read('state','draft');if(!state){const response=await fetch('seed.json');if(!response.ok)throw Error('Could not load initial portfolio content');const content=validate(await response.json());state={content,original:structuredClone(content),modified:false,baseline:null,config:{owner:'abhi18855-design',repo:'portfolio',branch:'main'},quality:82,maxEdge:1920};await save();}else if(state.content?.version!==1||!Array.isArray(state.content.projects))throw Error('Unsupported saved draft format.');$('#save-status').textContent='Saved on this device';render();}catch(err){fail(err);$('#save-status').textContent='Could not open draft';}
